import {COUNTRY} from './data.js?v=176';
import {esc,formatScore} from './ui.js?v=176';
export function prestigeHistory(s){const entries=s.prestigeLedger||[],f=s.factions[s.player],own=entries.filter(e=>e.faction===s.player);return `<section class="prestige-ledger"><h3>Votre prestige · ${formatScore(f.score)} points</h3><p>Chaque contribution est conservée avec son tour et son attribution. Les gains différés figurent au tour de leur attribution.</p>${!entries.length&&f.score?'<p>Cette sauvegarde précède le suivi détaillé. Les points déjà acquis sont conservés.</p>':''}${ledger(own)}${s.ended?`<details><summary>Historique de toutes les puissances</summary>${ledger(entries)}</details>`:''}</section>`;}
function ledger(entries){return entries.length?`<div class="table-scroll"><table><thead><tr><th>Tour</th><th>Pays</th><th>Contribution</th><th>Prestige</th></tr></thead><tbody>${[...entries].sort((a,b)=>(a.turn||0)-(b.turn||0)).map(e=>`<tr><td>${e.turn===null?'Antérieur':e.turn}</td><td>${esc(COUNTRY[e.faction].name)}</td><td>${esc(e.reason)}</td><td class="prestige-gain">+${formatScore(e.points)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Aucun gain de prestige enregistré.</p>';}
export function prestigeHint(type){return ({collect:'La collecte ne donne aucun prestige immédiat. Vérifier une preuve authentique rapporte +2 à votre pays, une fois par pièce et par pays.',analyze:'+2 au pays qui vérifie la preuve authentique, une seule fois par pièce et par pays ; aucun point pour une falsification.',surveil:'Gain différé : +2 au pays crédité de la localisation lors de l’arrestation.',prepare:'Gain différé : +2 au pays crédité de la préparation lors de l’arrestation.',arrest:'+2 pour l’interpellation, +2 pour la localisation et +2 pour la préparation, attribués aux pays concernés : jusqu’à +6 pour votre pays.',hack:'+2 au pays qui vérifie la preuve authentique. Aucun prestige direct pour le hack ou la recherche ; aucune localisation.',drone:'Gain différé : +2 au pays crédité de la localisation lors de l’arrestation. Aucune preuve recueillie ; aucun prestige direct pour le bonus tactique.',protect:'Si une attaque est déjouée : 6 points partagés à parts égales entre les pays défenseurs. Aucun point pour la protection seule.',counter:'Aucun prestige direct pour la recherche ou la détection. Ne protège pas le QG.'})[type]||'';}
